package com.yeni.backoffice.api.payment.rest;
import com.yeni.backoffice.core.payment.dto.PgReconciliationDtos.*;import com.yeni.backoffice.core.payment.service.PgSettlementReconciliationService;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.nio.charset.StandardCharsets;import java.time.LocalDate;import java.util.List;
@RestController @RequestMapping("/admin/api/pg-reconciliation")
public class PgSettlementReconciliationRestController{private final PgSettlementReconciliationService service;public PgSettlementReconciliationRestController(PgSettlementReconciliationService service){this.service=service;}@GetMapping public ResponseEntity<List<ImportResponse>> list(){return ResponseEntity.ok(service.list());}@GetMapping("/{id}")public ResponseEntity<ImportResponse> get(@PathVariable Long id){return ResponseEntity.ok(service.get(id));}@GetMapping(value="/sample",produces="text/csv;charset=UTF-8")public ResponseEntity<byte[]> sample(@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate businessDate,@RequestParam(defaultValue="MATCHED") String scenario){boolean mismatch="MISMATCH".equalsIgnoreCase(scenario);byte[] content=("\uFEFF"+service.sampleCsv(businessDate,mismatch)).getBytes(StandardCharsets.UTF_8);String name="pg-settlement-"+businessDate+(mismatch?"-mismatch":"-matched")+".csv";return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+name+"\"").contentType(new MediaType("text","csv",StandardCharsets.UTF_8)).body(content);}@PostMapping(value="/imports",consumes="multipart/form-data")public ResponseEntity<ImportResponse> upload(@RequestPart MultipartFile file,@RequestParam String pgCompany,@RequestParam String mid,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate businessDate)throws Exception{return ResponseEntity.ok(service.importCsv(file.getOriginalFilename(),pgCompany,mid,businessDate,new String(file.getBytes(),StandardCharsets.UTF_8)));}@PatchMapping("/rows/{rowId}/resolution")public ResponseEntity<RowResponse> resolve(@PathVariable Long rowId,@RequestBody ResolutionRequest request){return ResponseEntity.ok(service.updateResolution(rowId,request));}}
